    'What’s New' => 'موارد جدید',
    'When enabled, site requests will return a service unavailable response and queued jobs will pause.' => 'در صورت فعال بودن، درخواست‌های سایت پاسخ «سرویس در دسترس نیست» برمی‌گردانند و کارهای صف متوقف می‌شوند.',
    'When someone replaces a file, the record of who uploaded the file will be updated as well.' => 'در صورتی که فردی فایلی را جایگزین کند، سابقه فردی که فایل را بارگذاری می‌کند نیز به روز رسانی می‌شود.',
    'Where assets should be stored (relative to **Asset Location**) when they are uploaded directly to the field.' => 'جایی که فایل‌های پروژه باید نگهداری گردند (نسبت به **مکان فایل پروژه**) زمانی که آن‌ها مستقیما به فیلد آپلود می‌شوند.',
    'Where assets should be stored on the filesystem.' => 'جایی که دارایی‌ها باید در فایل سیستم ذخیره شوند.',
    'Where assets should be stored when they are uploaded directly to the field.' => 'جایی که فایل‌های پروژه باید نگهداری گردند زمانی که آن‌ها مستقیما به فیلد آپلود می‌شوند.',
    'Where do you want to store user photos? Note that the subfolder path can contain variables like {username}.' => 'می‌خواهید عکس‌های کاربران را کجا ذخیره کنید؟ توجه داشته باشید که مسیر زیرپوشه می‌تواند شامل متغیرهایی مانند {username} باشد.',
    'Where new {type} should be placed by default in the field.' => 'جایی که {type} جدید باید به طور پیش فرض در فیلد قرار گیرد.',
    'Where new {type} should be placed by default in the structure.' => 'جایی در ساختار که {type} جدید به‌طور پیش‌فرض باید در آن قرار بگیرد.',
    'Where transforms should be stored on the filesystem.' => 'جایی که تغییر‌شکل‌ها باید در سیستم‌فایل نگهداری شود.',
    'Whether HTML should be encoded before rendering the Markdown.' => 'اینکه آیا HTML پیش از نمایش Markdown باید رمزگذاری شود.',
    'Whether authors should be able to choose which time zone the time is in.' => 'این که نویسندگان باید بتوانند منطقه زمانی که در آن هستند را انتخاب نمایند.',
    'Whether authors should be able to upload files directly to the field, rather than requiring them to select/upload assets via the selection modal.' => 'آیا نویسندگان باید بتوانند فایل‌ها را مستقیماً در فیلد بارگذاری کنند، به جای آنکه موظف باشند فایل‌های پروژه را از طریق مودال انتخاب، انتخاب/بارگذاری کنند.',
    'Whether buttons should only show their icons, hiding their text labels.' => 'آیا دکمه‌ها فقط باید نمادهای خود را نشان دهند و برچسب‌های متنی خود را پنهان کنند.',
    'Whether card views which include this field should show the custom ON/OFF labels, rather than the field name.' => 'اینکه آیا نماهای کارتی که شامل این فیلد هستند، باید به جای نام فیلد، برچسب‌های روشن/خاموش سفارشی را نشان دهند یا خیر.',
    'Whether custom fields should be validated during public registration.' => 'آیا فیلدهای سفارشی در طی ثبت نام عمومی باید اعتبارسنجی شوند.',
    'Whether the editor should show character, word, and line counts.' => 'اینکه آیا ویرایشگر باید تعداد نویسه‌ها، کلمات و خطوط را نمایش دهد.',
    'Whether the editor toolbar should be visible.' => 'اینکه آیا نوار ابزار ویرایشگر باید قابل مشاهده باشد.',
    'Whether the element index should allow viewing nested {type} in a table.' => 'اینکه نمایه عنصر باید اجازه مشاهده {type} تودرتو در جدول را بدهد.',
    'Whether the field should only render inline Markdown, without wrapping paragraphs.' => 'اینکه آیا فیلد فقط Markdown درون‌خطی را بدون پاراگراف‌بندی نمایش دهد.',
    'Whether the number of elements in this source should be shown beside it in the navigation.' => 'اینکه آیا تعداد مؤلفه‌های این منبع باید در کنار آن در ناوبری نمایش داده شود.',
    'Whether the site menu should be shown for {type} selection modals.' => 'آیا منو سایت برای مودال‌های انتخاب {type} نمایش داده شود یا خیر.',
    'Whether the structure of the related {type} should be maintained.' => 'آیا ساختار {type} مرتبط باید حفظ شود یا خیر.',
    'Whether the table rows should be restricted to those defined by the “Default Values” setting.' => 'خواه سطرهای جدول باید محدود به آنهایی باشد که توسط تنظیمات «مقادیر پیش‌فرض» تعریف شده‌اند.',
    'Whether this can be dismissed by a user and not shown again.' => 'آیا می‌تواند توسط یک کاربر رد شود و دوباره نشان داده نشود.',
    'Whether to show entries that the user doesn’t have permission to view, per the “View other users’ entries” permission.' => 'آیا ورودی‌هایی که کاربر مجوز مشاهده آنها را ندارد، با توجه به مجوز «مشاهده ورودی‌های کاربران دیگر» نشان داده شود یا خیر.',
    'Whether to show files that the user doesn’t have permission to view, per the “View files uploaded by other users” permission.' => 'گزینه نمایش فایل‌هایی که کاربران بنا بر مجوز «مشاهده فایل‌های بارگذاری‌شده به وسیله کاربران» مجاز به مشاهده نیستند.',
    'Whether to show sections that the user doesn’t have permission to view.' => 'آیا بخش‌هایی که کاربر اجازه مشاهده آن‌ها را ندارد نمایش داده شود یا خیر.',
    'Whether to show volumes that the user doesn’t have permission to view.' => 'گزینه نمایش مخزن‌هایی که کاربران مجوز مشاهده آن را ندارند.',
    'Whether validation errors on the related {type} should prevent the source element from being saved.' => 'که آیا خطاهای اعتبارسنجی روی {type}ی مرتبط باید از ذخیره مؤلفه منبع جلوگیری نماید.',
    'Whether {type} elements should be allowed to relate to themselves.' => 'که آیا مؤلفه‌های {type} باید اجازه ارتباط با خودشان را داشته باشند.',
